create table if not exists public.menu_items(id bigint generated by default as identity primary key,name text not null,description text,price numeric(10,2) not null check(price>=0),category text not null default 'Other',is_available boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.orders(id bigint generated by default as identity primary key,table_number integer not null check(table_number>0),status text not null default 'new' check(status in('new','accepted','preparing','ready','served','cancelled')),total_amount numeric(10,2) not null check(total_amount>=0),created_at timestamptz not null default now());
create table if not exists public.order_items(id bigint generated by default as identity primary key,order_id bigint not null references public.orders(id) on delete cascade,menu_item_id bigint references public.menu_items(id),item_name text not null,quantity integer not null check(quantity>0),price numeric(10,2) not null check(price>=0),subtotal numeric(10,2) not null check(subtotal>=0));
alter table public.menu_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
drop policy if exists "public menu read" on public.menu_items; create policy "public menu read" on public.menu_items for select to anon,authenticated using(is_available=true);
drop policy if exists "public order insert" on public.orders; create policy "public order insert" on public.orders for insert to anon,authenticated with check(table_number>0 and total_amount>=0);
drop policy if exists "public order item insert" on public.order_items; create policy "public order item insert" on public.order_items for insert to anon,authenticated with check(quantity>0 and price>=0 and subtotal>=0);
drop policy if exists "v1 order read" on public.orders; create policy "v1 order read" on public.orders for select to anon,authenticated using(true);
drop policy if exists "v1 order update" on public.orders; create policy "v1 order update" on public.orders for update to anon,authenticated using(true) with check(true);
drop policy if exists "v1 order items read" on public.order_items; create policy "v1 order items read" on public.order_items for select to anon,authenticated using(true);
insert into public.menu_items(name,description,price,category) select 'Chicken 65','Crispy fried chicken',220,'Starters' where not exists(select 1 from public.menu_items where name='Chicken 65');
insert into public.menu_items(name,description,price,category) select 'Paneer Tikka','Grilled paneer with spices',180,'Starters' where not exists(select 1 from public.menu_items where name='Paneer Tikka');
insert into public.menu_items(name,description,price,category) select 'Butter Chicken','Creamy tomato chicken curry',280,'Main Course' where not exists(select 1 from public.menu_items where name='Butter Chicken');
